import {importMemory, normalizeMemory} from './study-memory.mjs';

export function createMemoryUI({getState,setMemory,setAutoSync,render,toast,modal,closeModal,confirmDialog,chooseFile,icon,esc,subject,navigate}) {
  const local = ['localhost','127.0.0.1','[::1]'].includes(location.hostname);
  let checkedAt=null, syncStatus='idle',syncError='',inflight=false;
  const formatTime=value=>value?new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'尚未更新';
  const profile=()=>getState().memory;
  const sourceName=p=>p?.source==='codex-local'?'Codex 本地学习记忆':p?.source==='chatgpt-import'?'导入的 ChatGPT 学习摘要':'手动学习摘要';

  function banner(){const p=profile();return `<div class="memory-banner"><span>${icon(p?'heart':'leaf')}<span>${p?'学习记忆正在帮助安排今天的内容':'让学习安排，更了解你一点'}<small>${p?'只作复习线索，掌握情况由自测确认':'连接历史学习话题，接着上次的思路继续'}</small></span></span><button class="text-btn" data-nav="memory">${p?'查看记忆':'连接学习记忆'} ${icon('chevron')}</button></div>`;}
  function view(){const p=profile();return `<section class="page-intro"><div><div class="eyebrow">REMEMBER WHERE YOU STARTED</div><h2>让每次学习，都接得上。</h2><p>把过往的学习线索，变成今天更合适的安排。</p></div><button class="btn" data-action="memory-import">${icon('plus')}更新学习记忆</button></section><div class="memory-layout"><section class="panel memory-overview"><div class="small-title">你的学习记忆<span class="badge">${p?'已启用个性安排':'等待连接'}</span></div><div class="memory-status"><span class="memory-emblem">${icon('heart')}</span><div><h3>${p?esc(sourceName(p)):'从一段学习摘要开始'}</h3><p>${p?`${p.focus.length} 个学习话题 · ${p.preferences.pace==='beginner'?'从基础讲清楚':'按正常节奏推进'} · ${p.preferences.method==='intuition-example-quiz'?'先直觉，再例题与自测':'示例与练习结合'}`:'导入 ChatGPT 整理的学习摘要，或在本地版连接 Codex 学习记忆。'}</p></div></div>${p?`<div class="memory-times"><span>本次读取 / 导入：${esc(formatTime(p.updatedAt))}（北京时间）</span>${p.sourceUpdatedAt?`<span>来源文件更新：${esc(formatTime(p.sourceUpdatedAt))}</span>`:''}</div>`:''}<div class="memory-actions"><button class="btn secondary" data-action="memory-import">${icon('upload')}粘贴或导入摘要</button>${local?`<button class="btn outline" data-action="memory-sync">${icon('refresh')}立即同步本地记忆</button><button class="text-btn" data-action="memory-toggle">${getState().settings.memoryAutoSync?'暂停自动同步':'开启自动同步'}</button>`:''}${p?`<button class="btn outline" data-action="memory-export">${icon('download')}导出到手机</button><button class="text-btn" data-action="memory-disconnect">断开学习记忆</button>`:''}</div><p class="form-hint" style="margin:16px 0 0">学习记忆保存在当前浏览器，也包含在完整备份中。只保留匹配的学科话题与教学偏好，原始聊天文字不保存。</p></section><section class="panel"><div class="small-title">连接状态 ${icon('info')}</div><div class="memory-connection"><strong>${local?'电脑本地版 · 自动读取可用':'手机 / 公开版 · 摘要导入'}</strong><p>${local?'打开本地版时读取一次，保持页面打开时每分钟检查学习记忆是否变化。':'公开网页通过粘贴或文件接收学习摘要；电脑与手机通过导入文件传递。'}</p>${local?`<p id="memory-sync-status" role="status">${!getState().settings.memoryAutoSync?'自动同步已暂停，可手动检查或重新开启。':syncStatus==='syncing'?'正在检查…':syncStatus==='ok'?`最近检查：${esc(formatTime(checkedAt))}`:syncStatus==='error'?esc(syncError):'正在准备连接本地学习记忆…'}</p>`:''}<p>ChatGPT 账户记忆：未直接连接。当前没有可用的账户记忆读取入口。</p><a href="https://learn.chatgpt.com/docs/customization/memories" target="_blank" rel="noopener noreferrer">了解 ChatGPT 与 Codex 记忆的区别 ↗</a></div></section></div><div class="section-heading" style="margin-top:28px"><h3>记忆里的学习话题<small>STUDY SIGNALS</small></h3><span class="badge">${p?.focus.length||0} 个话题</span></div>${p?`<div class="knowledge-layout">${p.focus.map(f=>`<article class="knowledge-card"><span class="subject-tag" style="align-self:flex-start">${esc(subject(f.subject).name)}</span><h3>${esc(f.title)}</h3><p>${esc(f.reason)}</p><div class="memory-topic-links">${f.lessonIds.map(id=>`<button class="text-btn" data-lesson="${esc(id)}">查看对应课程 ${icon('arrow')}</button>`).join('')}</div></article>`).join('')}</div>`:`<div class="empty-state">${icon('heart')}<h3>学习过的线索，也值得被记下。</h3><p>在 ChatGPT 中请它总结你正在学的内容、容易出错的地方和喜欢的讲解方式，再把摘要导入这里。</p><button class="btn secondary" data-action="memory-import">导入第一份学习摘要 ${icon('plus')}</button></div>`}<div class="info-box" style="margin-top:24px">导入后，今日清单会优先安排相关且尚未完成的知识点，自测答错的内容优先回顾。历史里“问过”或“学过”不会自动变成已掌握，也不会改写你的已有完成记录。</div>`;}

  function preview(value,source='chatgpt-import'){
    const next=typeof value==='object'?normalizeMemory(value):importMemory(value,{source});
    modal('预览这次学习记忆',`<p class="lesson-lede">按关键词匹配到 ${next.focus.length} 个学习话题。你可以取消不需要的条目。应用只保存所选学科线索与教学偏好，原始文字不会保存。</p><div class="memory-preview-topics">${next.focus.map(f=>`<label class="badge"><input type="checkbox" name="memory-topic" value="${esc(f.topicId)}" checked> ${esc(subject(f.subject).name)} · ${esc(f.title)}</label>`).join('')}</div><p class="form-hint">${esc(sourceName(next))} · 摘要整理时间 ${esc(formatTime(next.updatedAt))}。应用后替换当前学习记忆，完成记录与笔记保留。</p>`,`<button class="btn secondary" data-action="memory-import">返回编辑</button><button class="btn" id="apply-study-memory">${icon('check')}应用这份学习记忆</button>`);
    document.querySelector('#apply-study-memory').addEventListener('click',()=>{try{const selected=new Set([...document.querySelectorAll('input[name="memory-topic"]:checked')].map(el=>el.value));const current=normalizeMemory({...next,updatedAt:new Date().toISOString(),focus:next.focus.filter(f=>selected.has(f.topicId))});if(setMemory(current,{automatic:false})){closeModal();render();toast('学习记忆已应用，今日安排已调整。');}}catch(error){toast(error.message);}});
  }
  function importForm(){modal('让 ChatGPT 的学习摘要，接入拾知',`<p class="form-hint">粘贴与你的 C、Python、高数、线代学习有关的摘要，或导入拾知导出的学习记忆 JSON。这里没有 ChatGPT 账户登录或自动读取功能。</p><form id="memory-form"><div class="field"><label for="memory-text">学习记忆摘要</label><textarea id="memory-text" maxlength="200000" placeholder="例如：我在预习定义域、陪域和值域，C 语言练过素数判断，希望先讲直觉，再用例题和一题自测巩固。"></textarea></div><div class="form-actions"><button class="btn outline" type="button" data-action="memory-file">${icon('upload')}选择文件</button><button class="btn" type="submit">预览识别结果 ${icon('arrow')}</button></div></form>`);document.querySelector('#memory-form').addEventListener('submit',e=>{e.preventDefault();try{preview(document.querySelector('#memory-text').value);}catch(err){toast(err.message);}});}
  async function importFile(){const [file]=await chooseFile('.json,.md,.txt,application/json,text/plain,text/markdown');if(!file)return;if(file.size>200000){toast('学习摘要请控制在 200 KB 以内');return;}try{preview(await file.text());}catch(err){toast(err.message);}}
  function download(){const p=profile();if(!p)return;const file=new Blob([JSON.stringify(p,null,2)],{type:'application/json'}),url=URL.createObjectURL(file),a=document.createElement('a');a.href=url;a.download=`拾知学习记忆-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('学习记忆已导出，可在手机的学习记忆页导入。');}
  function updateStatus(){const el=document.querySelector('#memory-sync-status');if(el)el.textContent=!getState().settings.memoryAutoSync?'自动同步已暂停，可手动检查或重新开启。':syncStatus==='syncing'?'正在检查本地学习记忆…':syncStatus==='ok'?`最近检查：${formatTime(checkedAt)}`:syncError;}
  async function sync(manual=false){
    if(!local){if(manual)importForm();return;}
    if(inflight||!getState().settings.memoryAutoSync&&!manual)return;
    const startFingerprint=profile()?.fingerprint;
    inflight=true;syncStatus='syncing';updateStatus();
    try{
      const response=await fetch('./api/study-memory',{cache:'no-store',credentials:'same-origin',headers:{Accept:'application/json'},signal:AbortSignal.timeout(8000)});
      if(!response.ok)throw new Error(response.status===404?'本地记忆服务不可用，请使用 npm start 启动新版拾知。':'本地学习记忆暂时不可读，请稍后重试。');
      const body=await response.json();const next=normalizeMemory(body.profile);checkedAt=Date.now();syncStatus='ok';syncError='';
      if((!manual&&!getState().settings.memoryAutoSync)||profile()?.fingerprint!==startFingerprint)return;
      if(profile()?.fingerprint!==next.fingerprint||profile()?.source!=='codex-local'){
        if(setMemory(next,{automatic:true})){render();if(manual)toast('本地学习记忆已同步，今日安排已调整。');}
      }else if(manual)toast('已检查本地记忆，学习话题没有变化。');
    }catch(error){syncStatus='error';syncError=error.message||'本地学习记忆暂时不可读';if(manual)toast(syncError);}
    finally{inflight=false;updateStatus();}
  }
  async function handleAction(action){switch(action){case 'memory-import':importForm();return true;case 'memory-file':await importFile();return true;case 'memory-export':download();return true;case 'memory-sync':await sync(true);return true;case 'memory-toggle':if(setAutoSync(!getState().settings.memoryAutoSync)){render();if(getState().settings.memoryAutoSync)await sync();}return true;case 'memory-disconnect':confirmDialog('断开当前学习记忆？','将移除本机的学习话题摘要，并暂停自动同步。完成记录、笔记和电子书保留，之后可重新导入。',()=>{if(!setMemory(null,{automatic:false}))throw new Error('学习记忆暂未保存，请重试');},'断开并移除摘要');return true;default:return false;}}
  function start(){if(!local)return;sync();setInterval(()=>{if(!document.hidden)sync();},60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)sync();});}
  return {view,banner,handleAction,start,sync};
}
